index 76d1577..dea1991 100644
--- a/src/core/project.ts
+++ b/src/core/project.ts
@@ -6,12 +6,64 @@ export interface Record {
   warns: readonly string[];
 }

+const getConceptSignature = (text: string): Set<string> => {
+  const concepts = new Set<string>();
+  const lower = text.toLowerCase();
+
+  if (/ops|operations?|operational|operator|maintain/.test(lower)) concepts.add("operational");
+  if (/infrastructure|stateful|service|component|tier|cache/.test(lower)) concepts.add("infra");
+  if (/burden|cost|overhead|run|always.?on/.test(lower)) concepts.add("burden");
+
+  return concepts;
+};
+
+const deduplicateEntries = (entries: readonly string[]): string[] => {
+  if (entries.length <= 1) return [...entries];
+
+  const result: string[] = [];
+  const seen = new Set<number>();
+
+  for (let i = 0; i < entries.length; i++) {
+    if (seen.has(i)) continue;
+
+    const sigI = getConceptSignature(entries[i]);
+    if (sigI.size === 0) {
+      result.push(entries[i]);
+      seen.add(i);
+      continue;
+    }
+
+    let best = entries[i];
+    let bestLen = best.length;
+
+    for (let j = i + 1; j < entries.length; j++) {
+      if (seen.has(j)) continue;
+
+      const sigJ = getConceptSignature(entries[j]);
+      const overlap = [...sigI].filter(c => sigJ.has(c)).length;
+
+      if (overlap > 0) {
+        if (entries[j].length < bestLen) {
+          best = entries[j];
+          bestLen = best.length;
+        }
+        seen.add(j);
+      }
+    }
+
+    result.push(best);
+    seen.add(i);
+  }
+
+  return result;
+};
+
 export const project = (records: readonly Record[]): string => {
   const lines: string[] = [];
   for (const record of records) {
-    for (const entry of record.ruledOut) lines.push(`- ruled out: ${entry}`);
-    for (const limit of record.limits) lines.push(`- limit: ${limit}`);
-    for (const warn of record.warns) lines.push(`- warn: ${warn}`);
+    for (const entry of deduplicateEntries(record.ruledOut)) lines.push(`- ruled out: ${entry}`);
+    for (const limit of deduplicateEntries(record.limits)) lines.push(`- limit: ${limit}`);
+    for (const warn of deduplicateEntries(record.warns)) lines.push(`- warn: ${warn}`);
   }
   return lines.join("\n");
 };
